def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> value
    write_time = {}  # key -> write time (for expiry)
    lru_order = []  # list of keys in order of use (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in write_time:
            return True
        return current_time >= write_time[key] + ttl

    def make_most_recent(key):
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    def evict_lru():
        if lru_order:
            # Remove expired entries from consideration first
            while lru_order:
                candidate = lru_order[0]
                if candidate in cache:
                    lru_order.pop(0)
                    del cache[candidate]
                    del write_time[candidate]
                    return
                else:
                    lru_order.pop(0)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove if expired
            if key in cache and is_expired(key, t):
                del cache[key]
                del write_time[key]
                if key in lru_order:
                    lru_order.remove(key)

            # Check if we need to evict
            if key not in cache and len(cache) >= capacity:
                evict_lru()

            # Store the value
            cache[key] = value
            write_time[key] = t
            make_most_recent(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if expired
            if key in cache and is_expired(key, t):
                del cache[key]
                del write_time[key]
                if key in lru_order:
                    lru_order.remove(key)
                results.append(-1)
            elif key in cache:
                # Key exists and not expired
                results.append(cache[key])
                make_most_recent(key)
            else:
                # Key not in cache
                results.append(-1)

    return results

